PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE `users` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `name` VARCHAR(255) NOT NULL, `email` VARCHAR(255) NOT NULL UNIQUE, `phone` VARCHAR(50), `role` VARCHAR(50) DEFAULT 'user', `wallet_balance` DOUBLE PRECISION DEFAULT '0', `subscription_plan` VARCHAR(100), `subscription_status` VARCHAR(50) DEFAULT 'INACTIVE', `property_video_url` TEXT, `property_verification_status` VARCHAR(50) DEFAULT 'PENDING', `avatar` TEXT, `status` VARCHAR(50) DEFAULT 'ACTIVE', `password` VARCHAR(255), `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `providers` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `name` VARCHAR(255) NOT NULL, `phone` VARCHAR(50) NOT NULL, `email` VARCHAR(255), `avatar` TEXT, `categories_json` TEXT, `services_json` TEXT, `rating` FLOAT DEFAULT '4.8', `total_jobs` INTEGER DEFAULT 0, `earnings` DOUBLE PRECISION DEFAULT '0', `is_online` TINYINT(1) DEFAULT 1, `status` VARCHAR(50) DEFAULT 'APPROVED', `location` VARCHAR(255), `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `bookings` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `booking_id` VARCHAR(100) NOT NULL UNIQUE, `user_id` INTEGER NOT NULL REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `provider_id` INTEGER REFERENCES `providers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, `category_name` VARCHAR(255) NOT NULL, `sub_category_name` VARCHAR(255), `service_name` VARCHAR(255) NOT NULL, `address_text` TEXT NOT NULL, `issue_description` TEXT, `issue_media_url` TEXT, `scheduled_date` VARCHAR(100), `scheduled_time` VARCHAR(100), `status` VARCHAR(100) DEFAULT 'PENDING_ADMIN_REVIEW', `inspection_report` TEXT, `service_charge` DOUBLE PRECISION DEFAULT '0', `parts_charge` DOUBLE PRECISION DEFAULT '0', `labour_charge` DOUBLE PRECISION DEFAULT '0', `discount_amount` DOUBLE PRECISION DEFAULT '0', `total_bill` DOUBLE PRECISION DEFAULT '0', `bill_status` VARCHAR(50) DEFAULT 'UNPAID', `before_media_url` TEXT, `after_media_url` TEXT, `completion_otp` VARCHAR(10) DEFAULT '4829', `is_otp_verified` TINYINT(1) DEFAULT 0, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `wallet_transactions` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `transaction_id` VARCHAR(100) NOT NULL UNIQUE, `user_id` INTEGER NOT NULL REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `booking_id` VARCHAR(100), `type` VARCHAR(50) NOT NULL, `amount` DOUBLE PRECISION NOT NULL, `balance_before` DOUBLE PRECISION NOT NULL, `balance_after` DOUBLE PRECISION NOT NULL, `description` TEXT, `status` VARCHAR(50) DEFAULT 'SUCCESSFUL', `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `subscription_plans` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `name` VARCHAR(100) NOT NULL, `price` DOUBLE PRECISION NOT NULL, `wallet_credit` DOUBLE PRECISION NOT NULL, `validity_months` INTEGER DEFAULT 12, `applicable_services` TEXT, `service_limits` VARCHAR(255), `description` TEXT, `features_json` TEXT, `is_recommended` TINYINT(1) DEFAULT 0, `status` VARCHAR(50) DEFAULT 'ACTIVE', `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `categories` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `name` VARCHAR(255) NOT NULL, `description` TEXT, `image_url` TEXT, `status` VARCHAR(50) DEFAULT 'ACTIVE', `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `sub_categories` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `category_id` INTEGER NOT NULL REFERENCES `categories` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `name` VARCHAR(255) NOT NULL, `description` TEXT, `image_url` TEXT, `status` VARCHAR(50) DEFAULT 'ACTIVE', `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `services` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `category_id` INTEGER NOT NULL REFERENCES `categories` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `sub_category_id` INTEGER NOT NULL REFERENCES `sub_categories` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `name` VARCHAR(255) NOT NULL, `description` TEXT, `image_url` TEXT, `pricing_model` VARCHAR(100) DEFAULT 'INSPECTION_BASED', `base_price` DOUBLE PRECISION DEFAULT '0', `status` VARCHAR(50) DEFAULT 'ACTIVE', `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `disputes` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `dispute_id` VARCHAR(100) NOT NULL UNIQUE, `booking_id` VARCHAR(100) NOT NULL, `user_id` INTEGER NOT NULL, `reason` VARCHAR(255) NOT NULL, `notes` TEXT, `status` VARCHAR(50) DEFAULT 'OPEN', `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `banners` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `title` VARCHAR(255) NOT NULL, `description` TEXT, `image_url` TEXT, `cta` VARCHAR(100), `redirect_type` VARCHAR(100), `status` VARCHAR(50) DEFAULT 'ACTIVE', `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `notifications` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `user_id` INTEGER, `provider_id` INTEGER, `title` VARCHAR(255) NOT NULL, `message` TEXT NOT NULL, `type` VARCHAR(50), `is_read` TINYINT(1) DEFAULT 0, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `chats` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `booking_id` VARCHAR(100), `sender` VARCHAR(100) NOT NULL, `text` TEXT NOT NULL, `time` VARCHAR(50), `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
DELETE FROM sqlite_sequence;
COMMIT;
